// Sets flag/bit fields on every moby in a zero-terminated index list.
void jet_group_state(int idx, int a, int b, int c) {
    short *list = gemlik_moby_groups[idx];
    if (list) {
        short *p = list;
        do {
            int off = (*(unsigned short *)p & 0x7FFF) << 8;
            struct Moby *m = (struct Moby *)((char *)(off + (int)gemlik_moby_array_start));
            if (*(char *)&m->state >= 0) {
                if (a != -1) {
                    if (a)
                        m->flags &= 0xFFFD;
                    else
                        m->flags |= 2;
                }
                if (b != -1) {
                    if (b) {
                        m->visible = 1;
                        m->flags &= 0xFFFE;
                    } else {
                        m->visible = 0;
                        m->flags |= 1;
                    }
                }
                if (c != -1) {
                    if (c)
                        m->collision = *(int *)(*(char **)&m->pclass + 0x10);
                    else
                        m->collision = 0;
                }
            }
        } while (*p++ >= 0);
    }
}
